        /** Spec D4c §3.1: vip_info; hong -> null (cache cung null). Loi RPC nem, giu cache cu. */
        async vipInfo() {
          const epoch = this.vipEpoch;
          const v = parseVipInfo(await this.call('platform.vip_info', {}));
          // Mua giao xong trong luc cho RPC: ban nay da cu -> khong dat cache, khong phat onVip (van tra cho nguoi goi).
          if (epoch !== this.vipEpoch) return v;
          this.lastVip = v;
          if (v !== null) this.noteVip(briefOf(v), false);
          return v;
        }
